{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.clarilayer/clarilayer",
  "title": "ClariLayer",
  "description": "Individual-analyst context layer over MCP: recall, remember, bootstrap, reconcile, and propose your data context. The live contract is discoverable at connect (capability v32).",
  "version": "0.1.0",
  "repository": {
    "url": "https://github.com/clarilayer/clarilayer",
    "source": "github"
  },
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://clarilayer.com/api/mcp/mcp",
      "headers": [
        {
          "name": "Authorization",
          "description": "Bearer cl_<your ClariLayer context key> — mint one at clarilayer.com via Connect your AI",
          "isRequired": true,
          "isSecret": true
        }
      ]
    }
  ]
}
